patch.content:
/* Shop.mn-ийн загвар */

body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
}

h1 { font-size: 36px; }

header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
}

.cart-count {
  background-color: #2563eb;
  color: #ffffff;
  border-radius: 999px;
  padding: 2px 10px;
}

.product-card {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
}

.product-card img { max-width: 100%; height: auto; }

.btn-add {
  background-color: #2563eb;
  color: #ffffff;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}

.product-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 768px) {
  .product-grid { grid-template-columns: 1fr 1fr; }
  header { flex-direction: row; justify-content: space-between; }
}

const title = document.querySelector("h1");
title.textContent = "Shop.mn — Монголын онлайн дэлгүүр";

document.querySelector('[data-testid="cart-count"]').textContent = "0";
